-- Признак агента, принятый в раунде 5: соседи по совместному просмотру (сессии за 7 дней, топ-30 на товар) от 5 товаров,
-- которые пользователь смотрел в наибольшем числе разных сессий за 14 дней, не меньше чем в двух. Колонки: максимум косинуса и сумма косинусов с весом ln(1 + сессии) и затуханием 96 ч.
-- {t} — якорь. Его подставляет песочница task1.extra, она же даёт запросу только таблицы hist и active_users.
-- Восстановление без LLM: скопировать файл в artifacts/task1/v2/extra/agent_night20_r5p5_cf_considered_seed_coview/feature.sql
-- и выполнить .venv/bin/python -m task1.extra agent_night20_r5p5_cf_considered_seed_coview --splits train val test
WITH seed AS (SELECT user_id, product_id, COUNT(DISTINCT user_session) AS ns, MAX(event_time) AS lt FROM hist WHERE event_type = 'view' AND event_time >= TIMESTAMP '{t}' - INTERVAL 14 DAY AND user_session IS NOT NULL AND user_id IN (SELECT user_id FROM active_users) GROUP BY user_id, product_id HAVING COUNT(DISTINCT user_session) >= 2 QUALIFY ROW_NUMBER() OVER (PARTITION BY user_id ORDER BY COUNT(DISTINCT user_session) DESC, MAX(event_time) DESC) <= 5), sp AS (SELECT DISTINCT user_session, product_id FROM hist WHERE event_type = 'view' AND event_time >= TIMESTAMP '{t}' - INTERVAL 7 DAY AND user_session IS NOT NULL), ss AS (SELECT user_session FROM sp GROUP BY user_session HAVING COUNT(*) BETWEEN 2 AND 30), spf AS (SELECT sp.user_session, sp.product_id FROM sp JOIN ss ON ss.user_session = sp.user_session), deg AS (SELECT product_id, COUNT(*)::DOUBLE AS n FROM spf GROUP BY product_id), pr AS (SELECT a.product_id AS pa, b.product_id AS pb, COUNT(*) AS co FROM spf a JOIN spf b ON a.user_session = b.user_session AND a.product_id <> b.product_id WHERE a.product_id IN (SELECT DISTINCT product_id FROM seed) GROUP BY 1, 2 HAVING COUNT(*) >= 2), nb AS (SELECT pa, pb, cosv FROM (SELECT pr.pa, pr.pb, pr.co / SQRT(d1.n * d2.n) AS cosv FROM pr JOIN deg d1 ON d1.product_id = pr.pa JOIN deg d2 ON d2.product_id = pr.pb) QUALIFY ROW_NUMBER() OVER (PARTITION BY pa ORDER BY cosv DESC) <= 30) SELECT s.user_id, nb.pb AS product_id, MAX(nb.cosv) AS f_x_cf_consid_cv_cos_max, SUM(nb.cosv * LN(1.0 + s.ns) * EXP(-date_diff('second', s.lt, TIMESTAMP '{t}') / 3600.0 / 96.0)) AS f_x_cf_consid_cv_wsum FROM seed s JOIN nb ON nb.pa = s.product_id GROUP BY s.user_id, nb.pb
